ALTER TABLE users DROP CONSTRAINT users_role_check;
ALTER TABLE users ADD CONSTRAINT users_role_check CHECK(role IN ('member','admin','super_admin'));
CREATE OR REPLACE FUNCTION app_admin() RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT coalesce(current_setting('app.role',true),'') IN ('admin','super_admin') $$;
ALTER TABLE messages ADD COLUMN seq bigint GENERATED ALWAYS AS IDENTITY;
CREATE UNIQUE INDEX messages_seq_unique ON messages(seq);
CREATE INDEX messages_conversation_seq ON messages(conversation_id,seq DESC);
CREATE TABLE conversation_reads(user_id uuid NOT NULL REFERENCES users,conversation_id uuid NOT NULL REFERENCES conversations,last_seq bigint NOT NULL DEFAULT 0 CHECK(last_seq>=0),PRIMARY KEY(user_id,conversation_id));
CREATE TABLE user_blocks(blocker_id uuid NOT NULL REFERENCES users,blocked_id uuid NOT NULL REFERENCES users,created_at timestamptz NOT NULL DEFAULT now(),CHECK(blocker_id<>blocked_id),PRIMARY KEY(blocker_id,blocked_id));
CREATE TABLE conversation_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),conversation_id uuid NOT NULL REFERENCES conversations,reporter_id uuid NOT NULL REFERENCES users,reason text NOT NULL CHECK(length(reason) BETWEEN 10 AND 2000),status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','resolved')),created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_open_conversation_report ON conversation_reports(conversation_id,reporter_id) WHERE status='open';
CREATE TABLE support_tickets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES users,subject text NOT NULL CHECK(length(subject) BETWEEN 5 AND 150),status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','closed')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE support_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),ticket_id uuid NOT NULL REFERENCES support_tickets,actor_id uuid NOT NULL REFERENCES users,body text NOT NULL CHECK(length(body) BETWEEN 1 AND 3000),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX support_ticket_owner ON support_tickets(owner_id,updated_at DESC);
CREATE INDEX support_message_ticket ON support_messages(ticket_id,created_at);
GRANT SELECT ON conversation_reads,user_blocks,conversation_reports,support_tickets,support_messages TO marketplace_app;
ALTER TABLE conversation_reads ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_reads ON conversation_reads FOR SELECT USING(user_id=app_user());
ALTER TABLE user_blocks ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_blocks ON user_blocks FOR SELECT USING(blocker_id=app_user());
ALTER TABLE conversation_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_reports ON conversation_reports FOR SELECT USING(reporter_id=app_user() OR app_admin());
ALTER TABLE support_tickets ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_tickets ON support_tickets FOR SELECT USING(owner_id=app_user() OR app_admin());
ALTER TABLE support_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY ticket_messages ON support_messages FOR SELECT USING(EXISTS(SELECT 1 FROM support_tickets t WHERE t.id=ticket_id));
CREATE FUNCTION pair_is_blocked(a uuid,b uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_blocks WHERE (blocker_id=a AND blocked_id=b) OR (blocker_id=b AND blocked_id=a)) $$;
REVOKE ALL ON FUNCTION pair_is_blocked(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION pair_is_blocked(uuid,uuid) TO marketplace_app;
CREATE FUNCTION guard_blocked_messages() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE c public.conversations%ROWTYPE;
BEGIN SELECT * INTO c FROM public.conversations WHERE id=NEW.conversation_id;
IF public.pair_is_blocked(c.buyer_id,c.seller_id) THEN RAISE EXCEPTION 'This conversation is blocked. New messages are unavailable.'; END IF;
RETURN NEW; END $$;
REVOKE ALL ON FUNCTION guard_blocked_messages() FROM PUBLIC;
CREATE TRIGGER blocked_message_guard BEFORE INSERT ON messages FOR EACH ROW EXECUTE FUNCTION guard_blocked_messages();
INSERT INTO migrations VALUES(6);
